use std::collections::BTreeMap;

use anyhow::{bail, Result};

pub(in crate::program_module::runtime::foreign_process) fn validate_name(name: &str) -> Result<()> {
    if name.is_empty() || name.trim() != name || name.len() > 128 {
        bail!("foreign-process capsule name must be bounded non-empty text");
    }
    if name.chars().any(char::is_control) {
        bail!("foreign-process capsule name must not contain control characters");
    }
    Ok(())
}

pub(in crate::program_module::runtime::foreign_process) fn validate_arguments(
    arguments: &[String],
    has_script: bool,
) -> Result<()> {
    if arguments.len() > 16 {
        bail!("foreign-process runtime exceeds the 16-argument limit");
    }
    let mut placeholders = 0usize;
    for argument in arguments {
        if argument.len() > 1024 || argument.chars().any(|value| value == '\0') {
            bail!("foreign-process runtime argument is invalid");
        }
        placeholders += argument.matches("{script}").count();
    }
    if (has_script && placeholders != 1) || (!has_script && placeholders != 0) {
        bail!("foreign-process script placeholder binding is invalid");
    }
    Ok(())
}

pub(in crate::program_module::runtime::foreign_process) fn validate_environment(
    environment: &BTreeMap<String, String>,
) -> Result<()> {
    if environment.len() > 16 {
        bail!("foreign-process environment exceeds the 16-variable limit");
    }
    for (key, value) in environment {
        let valid_key = !key.is_empty()
            && key.len() <= 128
            && key.bytes().enumerate().all(|(index, byte)| {
                byte == b'_' || byte.is_ascii_alphabetic() || (index > 0 && byte.is_ascii_digit())
            });
        if !valid_key || value.len() > 1024 || value.chars().any(|item| item == '\0') {
            bail!("foreign-process environment entry is invalid");
        }
    }
    Ok(())
}

pub(in crate::program_module::runtime::foreign_process) fn validate_script_extension(
    extension: &str,
    has_script: bool,
) -> Result<()> {
    let valid = extension.len() <= 16
        && extension
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'.');
    if !valid || (has_script && extension.is_empty()) || (!has_script && !extension.is_empty()) {
        bail!("foreign-process script extension is invalid");
    }
    Ok(())
}

